from functools import wraps
from typing import Optional

"""Connection decorator utilities."""


def with_connection(method):
    """Decorator ensuring a connection alias is available for the call.

    Usage:
      @with_connection
      def some_method(..., connection: Optional[str] = None):
          # inside, 'connection' is the alias string; ConnectionManager is switched for the call
    """

    @wraps(method)
    def wrapper(self, *args, **kwargs):
        # Normalize alias: allow calling connection="ALIAS" or connection_alias="ALIAS"
        alias: Optional[str] = kwargs.pop('connection', None) or kwargs.pop('connection_alias', None)

        if alias is None:
            try:
                alias = self.context.connection_manager.get_connection()
            except RuntimeError as e:
                msg = (
                    "No connection alias set. Pass connection='ALIAS' or set default "
                    "via context.set_default_connection()."
                )
                raise RuntimeError(msg) from e

        # Switch ConnectionManager for the duration of the call and pass alias as 'connection'
        with self.context.connection_manager.with_connection(alias):
            kwargs['connection'] = alias
            return method(self, *args, **kwargs)

    return wrapper
